def count_pairs(words):
    pairs = []
    for i in range(len(words) - 1):
        pairs.append((words[i], words[i + 1]))
    pairs = sorted(pairs)
    result = []
    for p in pairs:
        if len(result) > 0 and result[-1][0] == p[0] and result[-1][1] == p[1]:
            result[-1] = (p[0], p[1], result[-1][2] + 1)
        else:
            result.append((p[0], p[1], 1))
    return result

